mapper.select:
SELECT 
FROM t_payment_intent
WHERE source_type = #{sourceType} AND source_id = #{sourceId}

mapper.update:
UPDATE t_payment_intent
SET intent_status = 'CANCELLED', version = version + 1, update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
WHERE payment_intent_id = #{intent.paymentIntentId} AND version = #{intent.version}
  AND intent_status = 'OPEN'
  AND active_attempt_id IS NULL AND successful_attempt_id IS NULL

UPDATE t_payment_intent
SET active_attempt_id = #{activeAttemptId}, version = version + 1,
update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
WHERE payment_intent_id = #{paymentIntentId} AND version = #{version}
  AND intent_status = 'OPEN' AND expires_at > UTC_TIMESTAMP(6)
  AND active_attempt_id IS NULL AND successful_attempt_id IS NULL

UPDATE t_payment_intent
SET active_attempt_id = NULL, intent_status = #{intentStatus,javaType=com.paytech.payment.execution.core.enums.IntentStatus,typeHandler=com.paytech.foundation.mybatis.typehandler.CodeEnumTypeHandler,jdbcType=VARCHAR},
successful_attempt_id =

    #{attemptId}
    NULL

,
version = version + 1, update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
WHERE payment_intent_id = #{intent.paymentIntentId} AND version = #{intent.version}
AND active_attempt_id = #{attemptId}
AND intent_status = 'OPEN' AND successful_attempt_id IS NULL

UPDATE t_payment_intent
SET active_attempt_id = NULL,
version = version + 1,
update_time = #{now,typeHandler=com.paytech.foundation.mybatis.typehandler.InstantTypeHandler,jdbcType=TIMESTAMP}
WHERE payment_intent_id = #{paymentIntentId} AND version = #{version}
AND active_attempt_id = #{activeAttemptId}
AND intent_status = 'OPEN' AND successful_attempt_id IS NULL
